//===- ctcompile/lib/CTJS/IR/CTJSOps.cpp - ctjs op verifiers and folders --===//
//
// Hand-written verifiers, folders and interface hooks for the ctjs dialect.
// Parsers, printers, builders and accessors are generated by TableGen.
//
// A verifier is written here only when an ODS constraint cannot express the
// check: a symbol-table lookup (ctjs.call_direct's arity against its callee),
// an attribute measured against variadic operands (ctjs.create_closure's
// `enclosing_indices`), or a property of the surrounding block or function
// (handler balance, resume-point numbering). Anything expressible with
// SameOperandsAndResultType, AllTypesMatch or operand types belongs in the ODS.
//
//===----------------------------------------------------------------------===//
#include "ctcompile/CTJS/IR/CTJSOps.h"

#include "mlir/IR/Builders.h"
#include "mlir/IR/BuiltinTypes.h"
#include "mlir/IR/OpImplementation.h"
#include "mlir/Interfaces/ControlFlowInterfaces.h"
#include "mlir/Interfaces/FunctionImplementation.h"

#include <cassert>
#include <cstddef>
#include <cstdint>

#define GET_OP_CLASSES
#include "ctcompile/CTJS/IR/CTJSOps.cpp.inc"

namespace ctcompile::ctjs {

//===----------------------------------------------------------------------===//
// ctjs.constant
//===----------------------------------------------------------------------===//

mlir::LogicalResult ConstantOp::verify() {
    // The attribute must be one of this dialect's, because of -0.0. A builtin
    // FloatAttr compares -0.0 equal to 0.0, so a fold across two constants that
    // differ only in the sign of zero would silently pick either, and `1 / -0`
    // is -Infinity where `1 / 0` is Infinity. The same
    // argument applies to NaN, which no builtin attribute distinguishes from
    // itself.
    //
    // AnyAttr in the ODS and a verifier here, rather than a constrained
    // operand: the set of acceptable attributes is "the ones this dialect
    // defines", which is a predicate over a C++ type rather than something a
    // TableGen constraint expresses.
    const mlir::Attribute value = getValue();
    if (isConstantAttr(value)) { return mlir::success(); }
    return emitOpError("expects a CTJS constant attribute (undefined, null, boolean, number, "
                       "string or bigint), but got ")
           << value;
}

//===----------------------------------------------------------------------===//
// ctjs.func
//===----------------------------------------------------------------------===//

// The three FunctionOpInterface / CallableOpInterface hooks, defined here rather
// than in extraClassDeclaration. MLIR declares these hooks for the operation but
// defines none of them. Declaring them inline in the ODS fails with "class
// member cannot be redeclared", and omitting them leaves an undefined reference
// from the interface's Model, so they are defined out of line here.
llvm::ArrayRef<mlir::Type> FuncOp::getArgumentTypes() {
    return getFunctionType().getInputs();
}

llvm::ArrayRef<mlir::Type> FuncOp::getResultTypes() {
    return getFunctionType().getResults();
}

mlir::Region * FuncOp::getCallableRegion() {
    return &getBody();
}

mlir::ParseResult FuncOp::parse(mlir::OpAsmParser & parser, mlir::OperationState & result) {
    // A custom assembly format, because a FunctionOpInterface operation's
    // signature is a type attribute built from separately parsed argument and
    // result lists, which assemblyFormat cannot express. MLIR ships the parser
    // for exactly this shape, so this calls it rather than hand-writing one.
    auto buildFuncType = [](mlir::Builder & builder, llvm::ArrayRef<mlir::Type> argTypes,
                            llvm::ArrayRef<mlir::Type> results,
                            mlir::function_interface_impl::VariadicFlag,
                            std::string &) { return builder.getFunctionType(argTypes, results); };
    return mlir::function_interface_impl::parseFunctionOp(
        parser, result, /*allowVariadic=*/false, getFunctionTypeAttrName(result.name),
        buildFuncType, getArgAttrsAttrName(result.name), getResAttrsAttrName(result.name));
}

void FuncOp::print(mlir::OpAsmPrinter & printer) {
    mlir::function_interface_impl::printFunctionOp(printer, *this, /*isVariadic=*/false,
                                                   getFunctionTypeAttrName(), getArgAttrsAttrName(),
                                                   getResAttrsAttrName());
}

mlir::LogicalResult FuncOp::verify() {
    // Checks that the signature is consistent with JavaScript calling rules.
    // A JavaScript function returns exactly one value. There is no `void`: a
    // body that falls off the end returns undefined, and the importer emits
    // that explicitly rather than leaving a function with no result.
    if (getFunctionType().getNumResults() != 1) {
        return emitOpError("must return exactly one value - a JavaScript function that falls off "
                           "its end returns undefined, which the importer makes explicit");
    }
    for (const mlir::Type result : getFunctionType().getResults()) {
        if (!mlir::isa<ValueType>(result)) {
            return emitOpError("must return a !ctjs.value, but returns ") << result;
        }
    }
    for (const mlir::Type argument : getFunctionType().getInputs()) {
        if (!mlir::isa<ValueType>(argument)) {
            return emitOpError("takes only !ctjs.value parameters, but takes ") << argument;
        }
    }
    return mlir::success();
}

//===----------------------------------------------------------------------===//
// ctjs.call_direct
//===----------------------------------------------------------------------===//

FuncOp CallDirectOp::getTarget() {
    return mlir::SymbolTable::lookupNearestSymbolFrom<FuncOp>(*this, getCalleeAttr());
}

mlir::LogicalResult CallDirectOp::verifySymbolUses(mlir::SymbolTableCollection & symbols) {
    // The symbol must be a ctjs.func with a body, and its entry block must take
    // exactly what this call passes. This is the closed-world claim, checked
    // where MLIR checks symbol uses, through the same interface func.call
    // uses. A skipped function emits no ctjs.func at all (ctjs-translate's
    // record_skipped), so "no such symbol" is also what a call into a refusal
    // looks like.
    auto callee = symbols.lookupNearestSymbolFrom<FuncOp>(*this, getCalleeAttr());
    if (!callee) {
        return emitOpError("'") << getCallee() << "' does not name a ctjs.func in this module";
    }
    if (callee.getBody().empty()) {
        return emitOpError("'") << getCallee() << "' has no body to call";
    }
    // The entry block's argument count, which matches the function type:
    // receiver, new.target, callee, then the parameters.
    const unsigned expected = callee.getBody().front().getNumArguments();
    const unsigned passed = static_cast<unsigned>(getArgOperands().size());
    if (passed != expected) {
        return emitOpError("passes ")
               << passed << " operand(s), but the entry block of '" << getCallee() << "' takes "
               << expected << " (receiver, new.target, callee and " << (expected - 3)
               << " parameter(s)) - the resolver pads a short call with undefined and refuses "
                  "a long one";
    }
    return mlir::success();
}

//===----------------------------------------------------------------------===//
// ctjs.push_handler / ctjs.pop_handler
//===----------------------------------------------------------------------===//

// BranchOpInterface, which is what makes the handler block reachable.
//
// Without it the handler is a successor no pass can see operands flowing into,
// and MLIR's own verifier cannot check that the block's arguments match what
// the branch supplies. Modelling push_handler as an ordinary operation instead
// would leave the handler block unreachable in the CFG and every pass would
// treat it as dead code.
mlir::SuccessorOperands PushHandlerOp::getSuccessorOperands(unsigned index) {
    assert(index < 2 && "push_handler has exactly two successors");
    return mlir::SuccessorOperands(index == 0 ? getBodyOperandsMutable()
                                              : getHandlerOperandsMutable());
}

/// Both successors must be blocks in the same region: an exception handler
/// records a frame and an address within it, so the unwinder cannot transfer
/// to a block in another region.
static mlir::LogicalResult verifySameRegionSuccessors(mlir::Operation * op) {
    for (mlir::Block * successor : op->getSuccessors()) {
        if (successor->getParent() != op->getParentRegion()) {
            return op->emitOpError("both successors must be blocks in the same region");
        }
    }
    return mlir::success();
}

mlir::LogicalResult PushHandlerOp::verify() {
    return verifySameRegionSuccessors(*this);
}

// ctjs.check is shaped like push_handler but is the other end of the same edge.
// push_handler's handler successor exists to keep the pad reachable; this one
// is the edge the emitted code actually takes, and it carries the register file
// as of the throw rather than as of the `try`.
mlir::SuccessorOperands CheckOp::getSuccessorOperands(unsigned index) {
    assert(index < 2 && "check has exactly two successors");
    return mlir::SuccessorOperands(index == 0 ? getContOperandsMutable()
                                              : getHandlerOperandsMutable());
}

mlir::LogicalResult BinaryStaticOp::verify() {
    switch (getKind()) {
    case BinaryKind::Add:
    case BinaryKind::BitAnd:
    case BinaryKind::BitOr:
    case BinaryKind::BitXor:
    case BinaryKind::Shl:
    case BinaryKind::Shr:
    case BinaryKind::UShr: return mlir::success();
    default:
        return emitOpError("kind ")
               << stringifyBinaryKind(getKind())
               << " has no static form: context::binary_op_static implements add, bitand, "
                  "bitor, bitxor, shl, shr and ushr and answers undefined for the rest";
    }
}

mlir::LogicalResult CheckOp::verify() {
    return verifySameRegionSuccessors(*this);
}

mlir::LogicalResult CatchLandOp::verify() {
    // It must be first in its block, because ct_aot_catch_land clears the pad
    // marker. A second one is not a second catch, and one reached on a normal
    // path reads a pad nothing set; the runtime can report neither.
    if (getOperation() != &getOperation()->getBlock()->front()) {
        return emitOpError("must be the first operation of its block - it consumes the pad "
                           "marker, so anything before it can reach a second one");
    }
    return mlir::success();
}

mlir::LogicalResult PopHandlerOp::verify() {
    // Handler pushes and pops must balance. The runtime's pop
    // (ct_aot_handler_pop in ctbrowser/include/ctbrowser/aot/helpers/
    // frames-and-bindings.def) removes the innermost handler without checking
    // the frame, so a function that pops a handler it never pushed silently
    // removes its caller's catch, and nothing reports it at run time.
    //
    // This verifier checks one block: two pops with no push between them in
    // the same block are always wrong, because a push is a terminator and so
    // cannot sit between them. Whole-function balance across the CFG is a
    // dataflow question for a pass, not for a per-operation verifier.
    mlir::Block * block = getOperation()->getBlock();
    if (block == nullptr) { return mlir::success(); }
    for (mlir::Operation & op : *block) {
        if (&op == getOperation()) { break; }
        if (mlir::isa<PopHandlerOp>(op)) {
            return emitOpError("two pops in one block with no push between them - handler balance "
                               "is a compiler invariant and the runtime cannot check it");
        }
    }
    return mlir::success();
}

//===----------------------------------------------------------------------===//
// ctjs.resume_point
//===----------------------------------------------------------------------===//

mlir::LogicalResult ResumePointOp::verify() {
    // Resume-point indices must be unique and dense within a function.
    // Generator lowering turns them into a switch over a saved state index: a
    // duplicate gives two states that cannot be told apart, and a gap gives a
    // switch arm that resumes nowhere.
    auto function = getOperation()->getParentOfType<FuncOp>();
    if (!function) { return mlir::success(); }
    llvm::SmallVector<bool> seen;
    bool duplicated = false;
    function.walk([&](ResumePointOp point) {
        const auto index = static_cast<std::size_t>(point.getIndex());
        if (seen.size() <= index) { seen.resize(index + 1, false); }
        if (seen[index]) { duplicated = true; }
        seen[index] = true;
    });
    if (duplicated) { return emitOpError("resume point indices must be unique in a function"); }
    for (std::size_t i = 0; i < seen.size(); ++i) {
        if (!seen[i]) {
            return emitOpError("resume point indices must be dense: ")
                   << i << " is missing while " << (seen.size() - 1) << " is present";
        }
    }
    return mlir::success();
}

//===----------------------------------------------------------------------===//
// ctjs.create_closure
//===----------------------------------------------------------------------===//

mlir::LogicalResult CreateClosureOp::verify() {
    // `enclosing_indices` is parallel with the capture list, not packed. A list
    // holding only the slots filled from the enclosing closure is the plausible
    // wrong reading, and it fails silently: every index past the first
    // from_parent_local slot would name a different capture, and the native
    // closure lift would pass the wrong binding into a function that compiles
    // cleanly and prints a wrong number.
    //
    // No ODS constraint can check this, because the length must match the
    // number of variadic operands.
    const mlir::DenseI32ArrayAttr indices = getEnclosingIndicesAttr();
    if (!indices) { return mlir::success(); }
    if (indices.size() != static_cast<std::int64_t>(getUpvalues().size())) {
        return emitOpError("`enclosing_indices` has ")
               << indices.size() << " entries for " << getUpvalues().size()
               << " capture operand(s) - the two are indexed in parallel with the target's "
                  "upvalue descriptors, and a packed list captures the wrong bindings silently";
    }
    // -1 is the only sentinel. It means "the operand beside me is the cell";
    // any other negative number is malformed.
    const llvm::ArrayRef<std::int32_t> entries = indices.asArrayRef();
    for (std::size_t i = 0; i < entries.size(); ++i) {
        if (entries[i] < -1) {
            return emitOpError("`enclosing_indices[")
                   << i << "]` is " << entries[i]
                   << "; the only negative entry is -1, which means the slot is filled from the "
                      "operand rather than from the enclosing closure";
        }
        // The two halves of a slot must agree. An index names an upvalue of the
        // enclosing closure, which is what the VM fills the slot from; the
        // operand beside it is then the importer's placeholder, because there
        // is no binding of this frame to point at. A slot that names an index
        // and also holds a real cell of this frame says two different things.
        //
        // That mistake still compiles. The native closure lift reads the
        // operand first (closureLifter::capturedValue in
        // CTNative/Lowering/ClosureLifting/Captures.cpp): a ctjs.create_cell
        // wins and the index is never read. If the index was the truth, the
        // lifted call passes this frame's binding where the enclosing closure's
        // upvalue belonged, and the program prints a wrong number.
        //
        // This cannot detect a permuted list: the target's upvalue descriptors
        // are not in the module, so `array<i32: 1, 0>` where the descriptors
        // want `0, 1` is two well-formed slots. The importer must get that
        // right; test/CTNative/Fixtures/Closures/nested-closure.js would catch
        // it by its output.
        if (entries[i] < 0) { continue; }
        if (getUpvalues()[i].getDefiningOp<CreateCellOp>() != nullptr) {
            return emitOpError("`enclosing_indices[")
                   << i << "]` is " << entries[i] << ", so slot " << i
                   << " is filled from the enclosing closure - but its capture operand is a "
                      "ctjs.create_cell of this frame, and the two describe the same slot "
                      "differently; the native lift believes the cell and the index is lost";
        }
        // More generally, a slot filled from the enclosing closure must carry
        // exactly the importer's `undefined` placeholder. A block-argument
        // operand (a from_parent_local binding held in a register) is the same
        // contradiction as a cell, except that capturedValue then takes the
        // index and drops the operand. This check covers the cell case above
        // too; that one is kept for its clearer error message.
        auto placeholder = getUpvalues()[i].getDefiningOp<ConstantOp>();
        if (!placeholder || !llvm::isa<UndefinedAttr>(placeholder.getValue())) {
            return emitOpError("`enclosing_indices[")
                   << i << "]` is " << entries[i] << ", so slot " << i
                   << " is filled from the enclosing closure and its capture operand has to be "
                      "the importer's `ctjs.constant #ctjs.undefined` placeholder - a real value "
                      "there is a second, contradictory answer for the same slot";
        }
    }
    return mlir::success();
}

} // namespace ctcompile::ctjs
